"""Exercise the settings window against a private fake Aether process."""
import os
from pathlib import Path
import subprocess
import tempfile

FAKE = "#!/usr/bin/python3\nimport json, sys, time\npayload = json.load(sys.stdin)\naction = sys.argv[1]\ncolors = dict(paper='#181616', ink='#c5c9c5', inkDeep='#c8c093', sumi='#a6a69c', indigo='#658594', green='#a9b665', sealRaw='#c4746e', bg='#99887766', warn='#c4746e', sep='#c5c9c52e', rowHi='#c5c9c50f', rowSel='#c4746e2e')\noverrides = payload.get('overrides', {})\nif overrides.get('qs_paper'): colors['paper'] = overrides['qs_paper']\nif action == '--quickshell-preview':\n    time.sleep(.65)\n    colors['bg'] = '#01020344'\nelif action == '--quickshell-apply':\n    colors['bg'] = '#aabbccdd'\nprint(json.dumps(dict(ok=True,revision='test-revision',source=dict(kind='scratch',name='',filename=''),defaults=colors,colors=colors,overrides=overrides)))\n"
QML = 'import QtQuick\nimport Quickshell\nimport "@DESKTOP@" as Desktop\nShellRoot {\n    Item {\n        id: theme\n        property color paper: "#181616"\n        property color bg: "#80181616"\n        property color ink: "#c5c9c5"\n        property color sumi: "#a6a69c"\n        property color sep: "#555555"\n        property color warn: "#c4746e"\n        property int previews: 0\n        property int accepted: 0\n        property var previewColors: null\n        property var acceptedColors: null\n        signal paletteCommitted()\n        function previewPalette(colors) { previews++; previewColors = colors; }\n        function cancelPreview() { previewColors = null; }\n        function acceptPalette(colors, revision) { accepted++; acceptedColors = colors; previewColors = null; paletteCommitted(); }\n    }\n    Item {\n        id: settings\n        property var panelOpacity: null\n        property var locusOpacity: null\n        property bool panelBlur: false\n        property bool locusBlur: false\n        property real panelScale: 1\n        property real locusScale: 1\n        property real panelTextScale: 1\n        property real locusTextScale: 1\n        property int normalWidth: 640\n        property int previewWidth: 1000\n        property int locusHeight: 0\n        property int windowWidth: 900\n        property int windowHeight: 700\n        property string lastError: ""\n        function setSetting(key, value) { settings[key] = value; }\n        function resetSection(name) {}\n    }\n    Desktop.SettingsWindow { id: win; theme: theme; settings: settings; aetherBin: "@AETHER@" }\n    Timer {\n        property int stage: 0\n        interval: 100; running: true; repeat: true\n        onTriggered: {\n            stage++;\n            if (stage === 1) win.open();\n            if (stage === 3) win.page = "Panels";\n            if (stage === 4) win.page = "Locus";\n            if (stage === 5) win.page = "Colors";\n            if (stage === 6) {\n                if (!win.palette || win.errorText || win.colors.bg !== "#99887766") { console.error("custom initial palette failed: " + win.errorText); Qt.exit(1); return; }\n                win.updateColor("paper", "#11223344");\n                if (!win.dirty || theme.previews !== 1 || win.colors.bg !== "#112233f0") { console.error("immediate preview failed"); Qt.exit(1); return; }\n            }\n            if (stage === 16) {\n                if (win.colors.bg !== "#01020344" || theme.previewColors.bg !== "#01020344") { console.error("backend preview failed: " + win.colors.bg); Qt.exit(1); return; }\n                win.updateColor("paper", "#44556677");\n            }\n            if (stage === 19) { if (!win.previewRunning) { console.error("stale preview did not start"); Qt.exit(1); return; } win.commit("apply", ""); }\n            if (stage === 30) {\n                if (win.errorText || win.dirty || theme.accepted !== 1 || !win.palette || win.colors.bg !== "#aabbccdd" || theme.previewColors !== null || theme.acceptedColors.bg !== "#aabbccdd") { console.error("stale preview replaced commit: " + win.errorText + " " + win.colors.bg); Qt.exit(1); return; }\n                console.log("settings runtime passed"); Qt.quit();\n            }\n        }\n    }\n}\n'

with tempfile.TemporaryDirectory(prefix="qs-settings-") as directory:
    root = Path(directory)
    binary = root / "aether"
    binary.write_text(FAKE)
    binary.chmod(0o755)
    desktop = Path(__file__).resolve().parents[1]
    (root / "shell.qml").write_text(QML.replace("@DESKTOP@", desktop.as_uri()).replace("@AETHER@", str(binary)))
    env = dict(os.environ, XDG_RUNTIME_DIR=directory, QT_QPA_PLATFORM="offscreen", QT_NO_XDG_DESKTOP_PORTAL="1")
    result = subprocess.run(["qs", "-p", directory], env=env, capture_output=True, text=True, timeout=15)
    output = result.stdout + result.stderr
    if result.returncode or "settings runtime passed" not in output or "WARN scene:" in output:
        print(output)
        raise SystemExit(1)
    print("settings window runtime passed")
